{
  "name": "octopus-to-magpie-connect",
  "version": "0.1.1",
  "description": "Magpie page plugin: connect a local Magpie gateway to an Octopus cloud node so it can serve Octopus Coding Plan models.",
  "type": "module",
  "main": "index.mjs",
  "scripts": {
    "test": "node --test tests/*.test.mjs"
  },
  "files": [
    "index.mjs",
    "src/",
    "page/"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "octopus",
    "magpie-plugin"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/lingyuins/octopus-to-magpie-connect.git"
  },
  "dependencies": {
    "ws": "8.22.0"
  },
  "magpie": {
    "icon": "https://raw.githubusercontent.com/lingyuins/octopus-to-magpie-connect/master/page/icon.svg",
    "page": {
      "title": "Octopus Connector",
      "titles": {
        "zh": "Octopus 连接器",
        "zh-TW": "Octopus 連接器"
      },
      "file": "page/index.html"
    }
  }
}
